<template><button class="ln-issue-card ln-focus-ring" :class="{selected}" type="button"><div class="ln-issue-card__top"><span>{{reqNo}}</span><div><small>{{typeLabel}}</small><LnBadge :tone="priorityTone">{{priority||'P2'}}</LnBadge></div></div><strong>{{title}}</strong><div class="ln-issue-card__context"><span>{{contextMain}}</span><i>·</i><span>{{contextTail}}</span></div><footer><span>{{footer}}</span><span class="ln-issue-card__owner"><i>{{ownerInitial}}</i>{{owner}}</span></footer></button></template>
<script setup lang="ts">
import{computed}from'vue';import LnBadge from'./LnBadge.vue'
const props=withDefaults(defineProps<{reqNo:string;title:string;typeLabel:string;priority?:string;contextMain?:string;contextTail?:string;footer?:string;owner?:string;selected?:boolean}>(),{priority:'P2',contextMain:'-',contextTail:'-',footer:'-',owner:'未分配'})
const priorityTone=computed<'neutral'|'accent'|'warning'|'danger'>(()=>props.priority==='P0'?'danger':props.priority==='P1'?'warning':props.priority==='P2'?'accent':'neutral');const ownerInitial=computed(()=>props.owner==='未分配'?'?':props.owner.slice(-1))
</script>
